  if (!valid) {
    console.error(validate.errors);
    return false;
  }
  return true;
}

function loadSchema(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

module.exports = {
  validateClaim,
  loadSchema
